import{_ as o,o as t,c as d,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"Deployment Runbook — AWS Account 134875421878 (5-EC2 + S3 KMS + Vast.ai GPU)","description":"","frontmatter":{},"headers":[],"relativePath":"operations/deployment-acct134.md","filePath":"operations/deployment-acct134.md"}'),a={name:"operations/deployment-acct134.md"};function r(n,e,i,s,l,u){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="deployment-runbook-—-aws-account-134875421878-5-ec2-s3-kms-vast-ai-gpu" tabindex="-1">Deployment Runbook — AWS Account <code>134875421878</code> (5-EC2 + S3 KMS + Vast.ai GPU) <a class="header-anchor" href="#deployment-runbook-—-aws-account-134875421878-5-ec2-s3-kms-vast-ai-gpu" aria-label="Permalink to &quot;Deployment Runbook — AWS Account `134875421878` (5-EC2 + S3 KMS + Vast.ai GPU)&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./README.html">← Operations Hub</a> · <a href="./wake-on-request.html">Wake-on-Request Architecture</a></p><p>Authoritative production deployment state and operational log for BrandHub in <strong>AWS <code>ap-southeast-1</code> (Singapore)</strong> under Account <code>134875421878</code>. Infrastructure-as-code and host manifests live at <code>prod/terraform/</code> (<code>01-iam</code> → <code>04-storage</code>) and <code>prod/hosts/</code> (<code>prod/hosts/README.md</code>).</p><hr><h2 id="_1-five-host-ec2-compute-inventory" tabindex="-1">1. Five-Host EC2 Compute Inventory <a class="header-anchor" href="#_1-five-host-ec2-compute-inventory" aria-label="Permalink to &quot;1. Five-Host EC2 Compute Inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Host Role</th><th style="text-align:left;">Instance ID</th><th style="text-align:left;">Private IP</th><th style="text-align:left;">Compose Manifests (<code>prod/hosts/</code>)</th><th style="text-align:left;">Running Containers &amp; Services</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>gateway</code></strong></td><td style="text-align:left;"><code>i-05f5bfca4452b0f83</code></td><td style="text-align:left;"><code>172.31.27.199</code></td><td style="text-align:left;"><code>prod/hosts/gateway/gateway.compose.json</code>, <code>gateway-wake.compose.yaml</code> (<code>~/brandhub/ecr</code>)</td><td style="text-align:left;"><strong>Nginx</strong> (<code>80/443</code>, Let&#39;s Encrypt TLS for <code>api.brandhub.id.vn</code> via <code>brandhub-certificate-renew.timer</code>), <strong><code>brandhub-api-gateway</code></strong> (<code>:8080</code>), <strong><code>brandhub-waker</code></strong> (<code>:8099</code> for <code>edit-video</code>)</td></tr><tr><td style="text-align:left;"><strong><code>core</code></strong></td><td style="text-align:left;"><code>i-01cba58d9f08be748</code></td><td style="text-align:left;"><code>172.31.24.149</code></td><td style="text-align:left;"><code>prod/hosts/core/core.compose.json</code>, <code>core-wake.compose.yaml</code> (<code>~/brandhub/ecr</code>)</td><td style="text-align:left;"><strong><code>brandhub-business-service</code></strong> (<code>:8081</code>), <strong><code>brandhub-publisher-service</code></strong> (<code>:8083</code>), <strong>PostgreSQL 17</strong> (<code>:5432</code>), <strong>Redis 7</strong> (<code>:6379</code>), <strong>RabbitMQ 3.13</strong> (<code>:5672</code>), <strong>ChromaDB</strong> (<code>:8000</code>), <strong><code>db-backup</code></strong> (<code>:8090</code>, 00:00 ICT S3 dumps), <strong><code>crawl-gate</code></strong> (<code>172.31.24.149:8084</code>) + <strong><code>brandhub-waker</code></strong></td></tr><tr><td style="text-align:left;"><strong><code>ai</code></strong></td><td style="text-align:left;"><code>i-0f7857edf71b6bb3f</code></td><td style="text-align:left;"><code>172.31.20.60</code></td><td style="text-align:left;"><code>prod/hosts/ai/ai.compose.json</code> (<code>~/brandhub/ecr</code>)</td><td style="text-align:left;"><strong><code>brandhub-ai-service</code></strong> (<code>:8082</code>, <code>c7i-flex.large</code>, <code>3 GiB</code> memory limit; connects to <code>core</code> Redis/RabbitMQ/Chroma via <code>extra_hosts</code> and <code>brandhub-ai-sg</code>)</td></tr><tr><td style="text-align:left;"><strong><code>crawl</code></strong></td><td style="text-align:left;"><code>i-0288d396a5d5b9b06</code></td><td style="text-align:left;"><code>172.31.20.50</code></td><td style="text-align:left;"><code>prod/hosts/crawl/crawl.compose.yaml</code> (<code>~/brandhub/crawl</code>)</td><td style="text-align:left;"><strong><code>crawl-service</code></strong> (<code>:8084</code>, Playwright/Camoufox; auto-sleeps when idle via <code>brandhub-idle-sleep.timer</code>)</td></tr><tr><td style="text-align:left;"><strong><code>edit-video</code></strong></td><td style="text-align:left;"><code>i-0ec7bf59c53fb7d0b</code></td><td style="text-align:left;"><code>172.31.20.80</code></td><td style="text-align:left;"><code>prod/hosts/edit-video/edit-video.compose.yaml</code> (<code>~/brandhub/edit-video</code>)</td><td style="text-align:left;"><strong><code>brandhub-edit-video</code></strong> (<code>:8095</code>, FFmpeg server timeline renderer; auto-sleeps when idle, wakes on HTTP request)</td></tr></tbody></table><hr><h2 id="_2-image-pinning-secret-delivery-iam-credentials" tabindex="-1">2. Image Pinning, Secret Delivery &amp; IAM Credentials <a class="header-anchor" href="#_2-image-pinning-secret-delivery-iam-credentials" aria-label="Permalink to &quot;2. Image Pinning, Secret Delivery &amp; IAM Credentials&quot;">​</a></h2><ul><li><strong>Immutable ECR Digests/Tags</strong>: Image tags (<code>BUSINESS_IMAGE</code>, <code>PUBLISHER_IMAGE</code>, <code>AI_IMAGE</code>, <code>GATEWAY_IMAGE</code>, <code>CRAWLER_IMAGE</code>, <code>DB_BACKUP_IMAGE</code>) sit in each host directory&#39;s <code>.env</code> alongside the Compose manifest (<code>sha-&lt;commit&gt;-acct134</code>), allowing deterministic <code>docker compose -f &lt;file&gt; up -d</code> rollouts and instant rollbacks.</li><li><strong>Instance Role Authentication (<code>01-iam</code>)</strong>: All static AWS IAM access keys were stripped from EC2 <code>env/*.env</code> (<code>chmod 0600</code>). <code>brandhub-business-service</code> (<code>DefaultCredentialsProvider</code>), <code>brandhub-ai-service</code> (<code>boto3</code>), and <code>db-backup</code> authenticate exclusively through the <code>brandhub-ec2-ecr-pull</code> EC2 Instance Profile over IMDSv2. Environment files are staged via short-lived encrypted S3 objects deleted immediately after pull—never passed in plaintext SSM command arguments.</li><li><strong>TLS Automation</strong>: <code>api.brandhub.id.vn</code> certificates are renewed automatically on <code>gateway</code> via <code>prod/hosts/gateway/certbot/brandhub-certificate-renew.{service,timer}</code> (<code>nginx -s reload</code> post-hook).</li></ul><hr><h2 id="_3-storage-kms-repository-vault-database-state-02-frontend-04-storage" tabindex="-1">3. Storage, KMS Repository Vault &amp; Database State (<code>02-frontend</code> &amp; <code>04-storage</code>) <a class="header-anchor" href="#_3-storage-kms-repository-vault-database-state-02-frontend-04-storage" aria-label="Permalink to &quot;3. Storage, KMS Repository Vault &amp; Database State (`02-frontend` &amp; `04-storage`)&quot;">​</a></h2><ul><li><strong>Repository &amp; Client Vault Bucket (<code>brandhub-media-134875421878</code>)</strong>: <ul><li><code>brandhub-business-service</code> stores <code>repository/</code> and <code>repository-staging/</code> objects encrypted with SSE-KMS (<code>alias/brandhub-repository-media-prod</code>) plus application-layer envelope encryption (<code>RepositoryEnvelopeCrypto</code>, <code>REPOSITORY_STORAGE_SYSTEMS3_BUCKET</code>, <code>REPOSITORY_SYSTEM_S3_KMS_KEY_ID</code>). Bucket policy enforces strict least privilege so console admin users cannot read raw tenant vault objects directly.</li></ul></li><li><strong>Public Rendered Media Bucket (<code>brandhubmedia-134875421878</code>)</strong>: Serves public <code>image/*</code> deliverables while keeping non-public prefixes private.</li><li><strong>Frontend Edge (<code>brandhub-web-prd-134875421878</code> + CloudFront)</strong>: Serves the <code>brandhub-web</code> Vite SPA (<code>VITE_API_BASE_URL=https://api.brandhub.id.vn</code>) behind CloudFront Function <code>prod/terraform/02-frontend/functions/brandhub-public-routes.js</code>.</li><li><strong>PostgreSQL &amp; Nightly Backups (<code>brandhub-db-backup-prd-134875421878</code>)</strong>: <ul><li><code>core.compose.json</code> runs against the restored production volume and applies incremental SQL migrations from <code>database/migrations/postgres/</code> (<code>97</code> tables in current baseline).</li><li>Nightly <code>00:00</code> ICT backups (<code>pg_dump -Fc</code> + <code>mongodump --archive --gzip</code>) are uploaded to <code>s3://brandhub-db-backup-prd-134875421878/</code> by the FastAPI <code>db-backup</code> container (<code>prod/hosts/core/db-backup/README.md</code>).</li></ul></li></ul><hr><h2 id="_4-dedicated-ai-host-external-vast-ai-gpu-worker" tabindex="-1">4. Dedicated AI Host &amp; External Vast.ai GPU Worker <a class="header-anchor" href="#_4-dedicated-ai-host-external-vast-ai-gpu-worker" aria-label="Permalink to &quot;4. Dedicated AI Host &amp; External Vast.ai GPU Worker&quot;">​</a></h2><ol><li><strong>AI Host Isolation (<code>brandhub-ai</code> — <code>172.31.20.60</code>)</strong>: <ul><li>Separated from <code>core</code> onto a dedicated <code>c7i-flex.large</code> (<code>40 GiB</code> <code>gp3</code>, Security Group <code>brandhub-ai-sg</code>).</li><li><code>business-service</code> and <code>crawl</code> route to <code>AI_SERVICE_URL=http://172.31.20.60:8082</code>; <code>ai-service</code> routes crawl triggers through <code>CRAWLER_API_URL=http://172.31.24.149:8084</code> (<code>crawl-gate</code> on <code>core</code>).</li><li>Enrolled in infrastructure health monitoring (<code>FR 3.10.3</code>) as <code>brandhub-ai</code>.</li></ul></li><li><strong>Vast.ai GPU Synthesis Worker (<code>gpu-workers/wan-vace/</code>)</strong>: <ul><li>Runs ComfyUI + <strong>Qwen Image 2.1</strong> (commercial ad image &amp; 4-angle product turnarounds) + <strong>Wan 2.2 Fun VACE 14B</strong> (<code>FLF2V</code> &amp; seam-chained product videos) + <strong>Wan 2.2 S2V 14B</strong> (lip-synced UGC) + local <strong>Ollama <code>qwen2.5vl:7b</code></strong> (<code>VLM_URL=http://127.0.0.1:11434</code>, models cached under <code>/workspace/ollama-models</code>) for visual pose/product description.</li><li>Uploads rendered assets directly to S3 using scoped IAM user <code>brandhub-worker-s3-uploader</code>.</li></ul></li></ol><hr><h2 id="_5-production-health-verification-checklist" tabindex="-1">5. Production Health Verification Checklist <a class="header-anchor" href="#_5-production-health-verification-checklist" aria-label="Permalink to &quot;5. Production Health Verification Checklist&quot;">​</a></h2><ul><li><code>GET https://api.brandhub.id.vn/actuator/health</code> → <code>200 UP</code> (<code>HTTP :80</code> → <code>308</code> HTTPS redirect; CORS allows <code>https://brandhub.id.vn</code>; unauthenticated protected routes return <code>401</code>).</li><li><code>core</code>: all core containers (<code>business</code>, <code>publisher</code>, <code>postgres</code>, <code>redis</code>, <code>rabbitmq</code>, <code>chromadb</code>, <code>db-backup</code>, <code>crawl-gate</code>, <code>waker</code>) report <code>healthy</code>.</li><li><code>ai</code>: reports Redis, RabbitMQ, ChromaDB heartbeat, and S3 connected; reaches <code>crawl-gate:8084</code> (<code>200</code> when awake, <code>503 STARTING</code> + auto-boot when <code>crawl</code> is stopped).</li><li><code>gateway</code> → <code>/edit-video/health</code>: returns <code>503 {&quot;status&quot;:&quot;STARTING&quot;}</code> + <code>Retry-After: 60</code> when <code>edit-video</code> is stopped and transitions EC2 instance <code>i-0ec7bf59c53fb7d0b</code> to <code>running</code>.</li></ul><hr><h2 id="_6-operational-caveats-maintenance-notes" tabindex="-1">6. Operational Caveats &amp; Maintenance Notes <a class="header-anchor" href="#_6-operational-caveats-maintenance-notes" aria-label="Permalink to &quot;6. Operational Caveats &amp; Maintenance Notes&quot;">​</a></h2><ul><li><strong>Crawler Ephemeral Auth Sessions</strong>: By security design, authenticated Facebook/Threads browser cookies on <code>crawl</code> reside in RAM only and must be re-uploaded via the crawler management API after a cold EC2 boot; proxy and TikTok configurations persist on encrypted disk when <code>CRAWLER_SECRET_KEY_FILE</code> is mounted.</li><li><strong>Historical Pre-Cutover Logs</strong>: For earlier <code>2026-10-29</code> and <code>2026-11-03</code> migration and RAM profiling logs, see <a href="./history/2026-10-29-ecr-deploy.html">2026-10-29 ECR Deploy</a>, <a href="./history/2026-11-03-rebalance-ai.html">2026-11-03 Rebalance AI</a>, and <a href="./history/2026-11-03-crawl-ram-check.html">2026-11-03 Crawl RAM Check</a>.</li></ul>',21)])])}const p=o(a,[["render",r]]);export{g as __pageData,p as default};
